css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .tabla-datos{border-collapse: collapse; font-size: 13.5px;}
.mz .tabla-datos th,.mz .tabla-datos td{border: 1.5px solid var(--bosque); padding: 5px 18px; text-align: center; font-weight: 700;}
.mz .tabla-datos th{background: #f3f3f3; font-size: 11.5px; font-family: sans-serif;}
.mz .tabla-datos .hueco-celda{min-width: 70px; height: 24px;}
.mz .e1-wrap{display: grid; grid-template-columns: auto 1fr; gap: 16px; align-items: start;}
.mz .preg-lista{display: flex; flex-direction: column; gap: 9px;}
.mz .preg-fila{font-size: 12.5px; line-height: 1.4;}
.mz .preg-hueco{display: inline-block; min-width: 50px; border-bottom: 1.5px solid var(--bosque); height: 18px; vertical-align: middle; margin-left: 4px;}
.mz .preg-hueco-grande{display: inline-block; min-width: 95px; border-bottom: 1.5px solid var(--bosque); height: 18px; vertical-align: middle; margin-left: 4px;}
.mz .e2-wrap{display: grid; grid-template-columns: 1fr auto; gap: 16px; align-items: center;}
.mz .texto-caja{border: 2px solid var(--bosque); border-radius: 10px; padding: 10px 14px; font-size: 13.5px; line-height: 1.6;}
.mz .op-lista{display: flex; flex-direction: column; gap: 9px;}
.mz .op-fila{display: grid; grid-template-columns: 1fr auto auto; gap: 10px; align-items: center; font-size: 12.5px; line-height: 1.35;}
.mz .op-caja{border: 1.5px dashed #000; border-radius: 8px; width: 110px; height: 30px; display: flex; align-items: center; justify-content: flex-start; padding-left: 8px; font-family: sans-serif; font-size: 9px; color: #777;}
.mz .res-caja{border: 1.5px solid var(--bosque); border-radius: 8px; width: 64px; height: 30px; display: flex; align-items: center; justify-content: flex-start; padding-left: 8px; font-family: sans-serif; font-size: 9px; color: #777;}
.mz .orden-fila{display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px;}
.mz .orden-item{text-align: center;}
.mz .orden-num{font-size: 12px; font-weight: 700; margin-bottom: 4px; font-family: sans-serif;}
.mz .orden-caja{border: 2px solid var(--bosque); border-radius: 10px; height: 44px;}
.mz .orden-flecha{font-size: 12px; font-family: sans-serif; color: #555;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 9px;}
.mz .vf-fila{display: flex; justify-content: space-between; align-items: center; gap: 12px; font-size: 12.5px; line-height: 1.35;}
.mz .vf-pildoras{display: flex; gap: 8px; flex-shrink: 0;}
.mz .vf{display: inline-flex; align-items: center; justify-content: center; width: 26px; height: 26px; border: 1.5px solid var(--bosque); border-radius: 50%; font-weight: 700; font-size: 13px;}
.mz .preg-fila,.mz .texto-caja{line-height: 1.725 !important;}
